package com.agenda.clinica.config;
import com.agenda.clinica.entity.*; import com.agenda.clinica.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(EspecialidadRepository er,MedicoRepository mr){return args->{if(er.count()==0){for(String n:new String[]{"Medicina general","Pediatría","Cardiología","Dermatología","Ginecología"}){Especialidad e=new Especialidad();e.setNombre(n);er.save(e);}}if(mr.count()==0){for(String[] d:new String[][]{{"Dra. Laura Méndez","1"},{"Dr. Rafael Castillo","2"},{"Dra. Ana Pérez","3"}}){Medico m=new Medico();m.setNombre(d[0]);m.setEspecialidad(er.findById(Long.valueOf(d[1])).orElseThrow());mr.save(m);}}};} }
